    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_intent(root, locator, runner, received, ReleaseCheckout::AnyHead)
}

