575	pub(crate) fn observe_source<R: CommandRunner, D: DependencyResolver>(
576	    workspace: &Workspace<'_, R, D>,
577	    trust_profile: ExecutionTrustProfileV1,
578	    checkout: ReleaseCheckout,
579	) -> Result<SourceIdentity, GraphError> {
580	    Ok(source_from_trust(&observe_git_trust(
581	        workspace,
582	        trust_profile,
583	        checkout,
584	    )?))
585	}
586	
587	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
588	    workspace: &Workspace<'_, R, D>,
589	    trust_profile: ExecutionTrustProfileV1,
590	    checkout: ReleaseCheckout,
591	) -> Result<GitCommitTrustEvidence, GraphError> {
592	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
593	        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
594	    }
595	    let evidence = workspace.git_access().observe_git_commit_trust()?;
596	    if evidence.canonical_root() != workspace.root {
597	        return Err(GraphError::ReleasePreconditionUnmet {
598	            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
599	        });
600	    }
601	    if checkout == ReleaseCheckout::Detached && evidence.head_disposition() != GitHeadDisposition::Detached {
602	        return Err(GraphError::ReleasePreconditionUnmet {
603	            requirement: ReleasePreconditionRequirement::DetachedHead,
604	        });
605	    }
606	    Ok(evidence)
607	}
608	
609	fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
610	    SourceIdentity::GitCommit {
611	        sha: evidence.head().clone(),
612	    }
613	}
